  if (/\bnao\s+(?:e|sera|trata-se de)\s+(?:uma?\s+)?(?:fachada|forro|testeira|revestimento)\b/.test(text)) {
    return false;
  }
  if (decision?.psa_confirmed === true || facts?.psa_aplicacao?.value === true || priorCommercial?.psa_confirmed === true) {
    return true;
  }
  if (['forro_metalico', 'brise'].includes(family)) return true;
  return /\b(?:fachadas?|forros?(?:\s+metalic\w*)?|testeiras?|revestimentos?)\b/.test(text);
}

function parseLocalizedNumber(raw) {
  if (typeof raw !== 'string') return undefined;
  if (!/^(?:\d{1,3}(?:\.\d{3})+|\d+)(?:,\d+)?$/.test(raw) && !/^\d+\.\d+$/.test(raw)) return undefined;
  const n = Number(raw.includes(',') || /^\d{1,3}(?:\.\d{3})+$/.test(raw)
    ? raw.replace(/\./g, '').replace(',', '.') : raw);
  return Number.isFinite(n) && n > 0 ? n : undefined;
}

function resolveCommercialArea(facts = {}) {
  const verified = facts.area_m2_validada;
  if (typeof verified?.value === 'number' && Number.isFinite(verified.value) && verified.value > 0
      && /^(?:v6|catalogo_sdr)(?:_|$)/i.test(verified.source ?? '')) return verified.value;

  const quantity = normalizeUtterance(facts.quantidade?.value);
  const measurement = quantity.match(/(\d+(?:[.,]\d+)*)\s*(m²|m2|metros? quadrados?|pecas?|chapas?|paineis|pcs?)(?![a-z0-9])/u);
  if (measurement) {
    const amount = parseLocalizedNumber(measurement[1]);
    if (!amount) return undefined;
    if (/^(?:m²|m2|metros? quadrados?)$/u.test(measurement[2])) return amount;
    if (!Number.isInteger(amount)) return undefined;
    const dimensions = normalizeUtterance(facts.dimensoes?.value);
    if (/\b(?:area|total)\b/.test(dimensions)) return undefined;
    const measures = [...dimensions.matchAll(/(\d+(?:[.,]\d+)*)\s*(mm|cm|m)\b/g)];
    if (measures.length === 2 && /[x×]|\bpor\b/.test(dimensions)) {
      const toMeters = ([, rawMeasure, unit]) => {
        const n = parseLocalizedNumber(rawMeasure);
        return n ? n / { mm: 1000, cm: 100, m: 1 }[unit] : NaN;
      };
      const total = amount * toMeters(measures[0]) * toMeters(measures[1]);
      if (Number.isFinite(total) && total > 0) return total;
    }
    const dimension = dimensions.replace(/\s/g, '').replace(/×/g, 'x');
    if (/^(?:2(?:m)?x1m|1(?:m)?x2m|2000(?:mm)?x1000mm|1000(?:mm)?x2000mm)$/.test(dimension)) return amount * 2;
    if (/^(?:3(?:m)?x1m|1(?:m)?x3m|3000(?:mm)?x1000mm|1000(?:mm)?x3000mm)$/.test(dimension)) return amount * 3;
    return undefined;
  }

  const dimensions = normalizeUtterance(facts.dimensoes?.value);
  const dimArea = dimensions.match(/(\d+(?:[.,]\d+)*)\s*(?:m²|m2|metros?\s+quadrados?)(?![a-z0-9])/u);
  if (dimArea) return parseLocalizedNumber(dimArea[1]);
  return undefined;
}

function parseFirstJson(rawText) {
  const s = String(rawText || '').trim();
  try { return JSON.parse(s); } catch {}
  const start = s.indexOf('{');
  if (start === -1) throw new Error('JSON ausente na resposta');
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < s.length; i++) {
    const ch = s[i];
    if (inStr) {
      if (esc) esc = false;
      else if (ch === '\\') esc = true;
      else if (ch === '"') inStr = false;
    } else {
      if (ch === '"') inStr = true;
      else if (ch === '{') depth++;
      else if (ch === '}') {
        depth--;
        if (depth === 0) return JSON.parse(s.slice(start, i + 1));
      }
    }
  }
  throw new Error('JSON incompleto na resposta');
}

