function businessMinutesBetween(startIso, endIso) {
  const startMs = Date.parse(startIso);
  const endMs = Date.parse(endIso);
  if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return 0;
  const OFFSET_MS = -3 * 60 * 60 * 1000;
  const startLocal = new Date(startMs + OFFSET_MS);
  const endLocal = new Date(endMs + OFFSET_MS);
  let total = 0;
  const curDay = new Date(Date.UTC(startLocal.getUTCFullYear(), startLocal.getUTCMonth(), startLocal.getUTCDate()));
  const lastDay = new Date(Date.UTC(endLocal.getUTCFullYear(), endLocal.getUTCMonth(), endLocal.getUTCDate()));
  const clamp = (a, b, s, e) => Math.max(0, Math.min(b, e) - Math.max(a, s));
  for (let d = new Date(curDay); d <= lastDay; d.setUTCDate(d.getUTCDate() + 1)) {
    const dow = d.getUTCDay();
    if (dow === 0 || dow === 6) continue;
    const dayStart = d.getTime();
    const w1Start = dayStart + 7 * 60 * 60 * 1000;
    const w1End = dayStart + (11 * 60 + 30) * 60 * 1000;
    const w2Start = dayStart + (13 * 60 + 40) * 60 * 1000;
    const w2End = dayStart + (dow === 5 ? 16 : 17) * 60 * 60 * 1000;
    total += clamp(startLocal.getTime(), endLocal.getTime(), w1Start, w1End) + clamp(startLocal.getTime(), endLocal.getTime(), w2Start, w2End);
  }
  return Math.floor(total / 60000);
}

function decideDestination(input) {
  if (input.humanActive) return { status: 'operator_active' };
  if (input.confirmedPsaApplication && (!input.existingSeller || input.newQuote)) {
    return { status: 'resolved', destination: 'psa_fachadas_forros' };
  }
  if (['comex', 'compras', 'rh', 'suporte_humano'].includes(input.sector)) {
    return { status: 'resolved', destination: input.sector };
  }
  if (!input.newQuote && input.existingSeller && input.existingSeller !== 'suporte_humano') {
    return { status: input.deliveryConfirmed ? 'support' : 'delivery_pending' };
  }
  const missing = field => input.humanRequested || input.classificationExhausted
    ? { status: 'resolved', destination: 'suporte_humano' }
    : { status: 'needs_data', field };
  const destination = dedicated.get(input.productFamily);
  if (destination) return { status: 'resolved', destination };
  if (input.customerType === 'pf') return { status: 'resolved', destination: 'express' };
  if (['gradil_metalico', 'portao_gradil'].includes(input.productFamily)) {
    if (!input.customerType) return missing('customer_type');
    if (gradilSp01.has(input.region)) return { status: 'resolved', destination: 'gradil_sp01_rj_es_sul' };
    if (gradilSp02.has(input.region)) return { status: 'resolved', destination: 'gradil_sp02_mg_co_norte_ne' };
    return missing('region');
  }
  if (!input.productFamily) return missing('product_family');
  if (input.customerType !== 'pj') return missing('customer_type');
  switch (input.segment) {
    case 'serralheria': return { status: 'resolved', destination: 'serralheria' };
    case 'revenda': return { status: 'resolved', destination: 'chapa_moeda_revenda' };
    case 'industrial':
      return { status: 'resolved', destination: industrial.get(input.subsegment) ?? 'industria_supervisor' };
    case 'construcao':
      if (!Number.isFinite(input.areaM2) || input.areaM2 <= 0) return missing('area_m2');
      if (input.areaM2 <= 30) return { status: 'resolved', destination: 'express' };
      if (gradilSp01.has(input.region) || input.region === 'SP 02') {
        return { status: 'resolved', destination: 'construcao_sp_rj_sul_es' };
      }
      if (gradilSp02.has(input.region)) return { status: 'resolved', destination: 'construcao_mg_ne_co_norte' };
      return missing('region');
    default: return missing('company_activity');
  }
}

function decideHandoff(input) {
  const route = decideDestination(input);
  if (route.status !== 'resolved') return route;
  if (!input.quoteIntent && !input.humanRequested && !input.sector) return { status: 'collecting' };
  const isSector = ['comex', 'compras', 'rh', 'suporte_humano'].includes(route.destination);
  if (!input.contactAvailable && !input.humanRequested && input.sector !== 'comex' && input.sector !== 'rh') {
    return { status: 'needs_data', field: 'contact', destination: route.destination };
  }
  if (!input.humanRequested && !isSector && input.hasQuantityOrArea === false) {
    return { status: 'needs_data', field: 'area_m2', destination: route.destination };
  }
  const quick = input.humanRequested || (input.monitorInactivity && input.dataSufficient);
  const accepted = input.summaryAccepted === true && input.acceptedRevision != null
    && input.acceptedRevision === input.summaryRevision;
  if (!quick && !accepted) return { status: 'awaiting_summary_acceptance', destination: route.destination };
  return { status: 'ready', destination: route.destination };
}

