const x=typeof query==='string'?JSON.parse(query):query;
if (x.formula === 'area_total_pecas') {
  const { quantidade, comprimento_mm, largura_mm } = x.valores || {};
  if (!Number.isSafeInteger(quantidade) || quantidade < 1
      || ![comprimento_mm, largura_mm].every(v => Number.isFinite(v) && v > 0)) {
    return JSON.stringify({status:'erro', formula:x.formula, erro:'Informe quantidade inteira e duas dimensões positivas por peça, em milímetros.'});
  }
  const resultado = quantidade * comprimento_mm * largura_mm / 1e6;
  if (!Number.isFinite(resultado) || resultado <= 0) return JSON.stringify({status:'erro', formula:x.formula, erro:'Área fora da faixa numérica.'});
  return JSON.stringify({status:'ok', formula:x.formula, resultado, unidade:'m²'});
}
function massOfComponents(values) {
  const positive = value => typeof value === 'number' && Number.isFinite(value) && value > 0;
  const formula = 'massa_componentes';
  const fail = mensagem => ({ status: 'erro', formula, erro: { mensagem } });
  const area = values?.area_referencia_m2;
