function compactPendencies(facts) {
  const value = facts.pendencias?.value ?? [];
  const notes = (Array.isArray(value) ? value : [value]).flatMap(note => String(note).split(/;|\n/));
  const application = String(facts.aplicacao?.value || '').trim();
  const compact = notes.map(note => {
    const clean = note.trim().replace(/[.]+$/, '');
    const normalized = normalizeUtterance(clean);
    if (application && /\b(?:seguranca|estrutura|fixacao|normas|adequacao)\b/.test(normalized) && normalized.includes(normalizeUtterance(application))) {
      return 'Avaliar a adequação para ' + application + ' com a Engenharia';
    }
    if (/\b(?:viabilidade|confirmar|avaliar)\b.{0,36}\b(?:formato|dimensoes)\b/.test(normalized)) {
      return 'Confirmar a viabilidade das dimensões solicitadas';
    }
    return clean;
  }).filter(Boolean);
  return [...new Map(compact.map(note => [normalizeUtterance(note),note])).values()];
}

function sameQuestion(answer, question) {
  const text = normalizeUtterance(answer);
  const target = normalizeUtterance(question);
  return text.includes(target)
    || target.includes('qual produto') && /(?:qual (?:produto|aplicacao)|que produto)[^?]*\?/.test(text)
    || target.includes('atividade') && /\batividade\b[^?]*\?/.test(text)
    || target.includes('pessoa fisica') && /(?:pessoa fisica|pf)[^?]*(?:empresa|pj)[^?]*\?/.test(text)
    || target.includes('whatsapp') && /whatsapp[^?]*\?/.test(text)
    || target.includes('area aproximada') && /(?:area|m2|m²|quantidade|medidas)[^?]*\?/.test(text)
    || target.includes('cidade e o estado') && /(?:cidade|estado|sede)[^?]*\?/.test(text);
}

function handleSupportMode(committed, context, decision) {
  const state = committed.p_state;
  const facts = state.facts ?? {};
  const sellerName = context.handoff.seller_name || 'o vendedor responsável';
  const sIntent = decision.support_intent;
  const nowIso = new Date().toISOString();
  const sla = { ...(state.sla ?? { faltas: 0, etapa: 't0', claims: [] }) };
  const t0 = context.handoff.delivered_at;
  if (t0) sla.t0 = t0;
  if (decision.direct_contact_requested === true) {
    const id = context.handoff.opportunity_id;
    const previous = context.state.direct_contact_request === id;
    committed.p_state = {...context.state, direct_contact_request:id};
    const number = context.handoff.seller_whatsapp;
    committed.p_answer = {text: previous && /^55[0-9]{10,11}$/.test(number || '')
      ? 'O WhatsApp de ' + sellerName + ' é +' + number + '.'
      : previous ? 'O WhatsApp de ' + sellerName + ' está indisponível no cadastro. Posso ajudar você por aqui.'
      : sellerName + ' é o responsável por esta solicitação. Posso ajudar você por aqui.',source:'support'};
    return committed;
  }
  if (/^\s*quem\b|\b(?:qual|quem)\b.{0,30}\b(?:vendedor|responsavel)\b/.test(normalizeUtterance(context.payload.message))) {
    committed.p_answer = {text:sellerName + ' é o responsável pela sua cotação.',source:'support'};
    return committed;
  }
  if (t0 && isClarificationQuestion(context.payload.message)) {
    committed.p_answer = { text: 'A notificação da sua cotação foi entregue ao vendedor responsável. Você quer saber como funciona o encaminhamento?', source: 'support' };
    return committed;
  }

  if (sIntent === 'atendimento_confirmado' && !confirmsHumanAttendance(context.payload.message, context.survey_outcome)) {
    committed.p_answer = { text: 'Sua solicitação foi encaminhada ao vendedor responsável. Você quer saber como funciona o encaminhamento ou informou que já recebeu o retorno?', source: 'support' };
    return committed;
  }
  if (sIntent === 'atendimento_confirmado') {
    sla.etapa = 'atendido_confirmado';
    sla.resolved_at = nowIso;
    committed.p_state = { ...state, sla };
    committed.p_answer = { text: 'Registrei sua confirmação de atendimento. Se precisar complementar a cotação, estou por aqui.', source: 'support' };
    return committed;
  }
  if (sIntent === 'complemento_cotacao' && !isClarificationQuestion(context.payload.message)) {
    const fields = ['produto','produto_familia','quantidade','especificacao','dimensoes','material','espessura','furacao','aplicacao','particularidades','local_obra','pendencias'];
    const patch = Object.fromEntries(Object.entries(decision.patch || {}).filter(([key, entry]) =>
      fields.includes(key) && JSON.stringify(entry?.value) !== JSON.stringify(context.state.facts?.[key]?.value)));
    const hasAttachment = committed.p_attachments?.some(item=> item.status !== 'ilegivel' && item.text);
    if (!Object.keys(patch).length && !hasAttachment) {
      committed.p_state = context.state;
      if (!committed.p_answer.text.trim()) committed.p_answer = {text:'O que deseja complementar ou corrigir nessa cotação?',source:'support'};
      return committed;
    }
    sla.last_complement_at = nowIso;
    committed.p_state = { ...state, sla };
    committed.p_answer = { text: 'Recebi a informação adicional sobre a sua cotação. O encaminhamento ao vendedor está pendente.', source: 'support', case_action: {type:'complemento_cotacao', opportunity_id:context.handoff.opportunity_id, patch, pending:'vendedor'} };
    return committed;
  }
  if (sIntent === 'acompanhamento_pedido') {
    const repeated = decision.order_return_complaint === true && Boolean(sla.last_order_follow_up_at);
    sla.last_order_follow_up_at = nowIso;
    if (repeated) sla.order_complaint_count = (sla.order_complaint_count || 0) + 1;
    committed.p_state = { ...state, sla };
    committed.p_answer = {
      text: repeated ? 'Registrei que você continua aguardando retorno sobre o pedido. O encaminhamento para a equipe de suporte está pendente.'
        : 'Registrei sua solicitação de acompanhamento do pedido. O encaminhamento ao vendedor está pendente.',
      source: 'support',
      case_action: {type:'acompanhamento_pedido', opportunity_id:context.handoff.opportunity_id,
        pending:repeated ? 'suporte_humano' : 'vendedor'},
    };
    return committed;
  }
  if (sIntent === 'cobranca_atendimento' && !t0) {
    committed.p_state = { ...state, sla: { ...sla, last_pending_claim_at: nowIso } };
    committed.p_answer = { text: 'Registrei que você ainda aguarda retorno. A entrega da notificação inicial ao vendedor está pendente de confirmação.', source: 'support', case_action: {type:'cobranca_atendimento', opportunity_id:context.handoff.opportunity_id, pending:'entrega_inicial'} };
    return committed;
  }
  if (sIntent === 'cobranca_atendimento') {
    const etapa = sla.etapa || 't0';
    const refTime = etapa === 't0' ? t0 : etapa === 'primeira_cobranca' ? (sla.t1 || t0) : etapa === 'escalado_supervisor' ? (sla.t2 || t0) : (sla.t3 || t0);
    const mins = businessMinutesBetween(refTime, nowIso);
    let reply = '';
    if (etapa === 't0') {
      if (mins < 30) reply = 'O aviso inicial da sua cotação foi entregue a ' + sellerName + '. Registrei que você ainda aguarda retorno.';
      else { sla.faltas = 1; sla.etapa = 'primeira_cobranca'; sla.t1 = nowIso; reply = 'Registrei que você ainda aguarda retorno. O reforço ao vendedor está pendente.'; }
    } else if (etapa === 'primeira_cobranca') {
      if (mins < 30) reply = 'Registrei que você ainda aguarda retorno.';
      else { sla.faltas = 2; sla.etapa = 'escalado_supervisor'; sla.t2 = nowIso; reply = 'Registrei a nova solicitação de retorno. O encaminhamento à supervisão está pendente.'; }
    } else if (etapa === 'escalado_supervisor') {
      if (mins < 30) reply = 'Registrei que você ainda aguarda retorno.';
      else { sla.etapa = 'escalado_coordenacao'; sla.t3 = nowIso; reply = 'Registrei a nova solicitação de retorno. O encaminhamento à coordenação está pendente.'; }
    } else {
      reply = 'Registrei que você ainda aguarda retorno. O encaminhamento à coordenação está pendente.';
    }
    sla.claims = [...(sla.claims || []).slice(-19), { at: nowIso, mins, etapa: sla.etapa, faltas: sla.faltas }];
    committed.p_state = { ...state, sla };
    committed.p_answer = { text: reply, source: 'support', case_action: {type:'cobranca_atendimento', opportunity_id:context.handoff.opportunity_id, stage:sla.etapa} };
    return committed;
  }
  if (!sIntent) {
    committed.p_state = context.state;
    const asksStatus = /\b(?:andamento|status|faltou|avisad[oa]|recebeu|notificad[oa]|encaminh(?:ad[oa]|ar))\b/.test(normalizeUtterance(context.payload.message));
    if (asksStatus) {
      committed.p_answer = { text: sellerName + ' é o responsável pela sua solicitação. ' +
        (t0 ? 'A entrega da notificação inicial foi confirmada.' : 'Ainda não tive confirmação de que o pedido chegou ao vendedor.'), source: 'support' };
    }
    if (!committed.p_answer.text.trim()) committed.p_answer = {text:'Como posso ajudar com sua solicitação?',source:'support'};
    return committed;
  }
  if (sIntent === 'nao_comercial' || sIntent === 'outros') {
    const dest = ['comex','compras','rh','suporte_humano'].includes(decision.sector) ? decision.sector : 'suporte_humano';
    committed.p_request_key = 'sup-' + context.turn_id;
    committed.p_destination = dest;
    committed.p_state = { ...state, sla };
    committed.p_answer = { text: 'Recebi sua solicitação e já estou encaminhando para a equipe responsável.', source: 'support' };
    return committed;
  }
  return null;
}

function commercialTurn(committed, context, decision) {
  if (context.human_takeover === true) {
    committed.p_state = context.state;
    committed.p_answer = { text: '', source: 'operator', silent: true };
    committed.p_technical = {};
    return committed;
  }
  if (decision.new_entry_context) {
    context.state = decision.new_entry_context;
    context.handoff = null;
    context.returning = {lookup:'new_contact'};
  }
  const lookup = context.returning?.lookup;
  const trackingIssue = $('Montar contexto sem binários').first()?.json?.tracking_issue;
  const messageRaw = context.payload?.message || '';
  const onlyCode = /^\s*LINO\.[A-Z0-9]{6}\s*$/i.test(messageRaw);
  const onlyPhone = /^\s*(?:\+?55[ .-]*)?\(?[0-9]{2}\)?[ .-]*[0-9]{4,5}[ .-]*[0-9]{4}\s*$/.test(messageRaw);
  const returning = context.returning?.case;
  const name = context.state.facts?.nome?.value;
  const greeting = typeof name === 'string' && name.trim() ? 'Olá, ' + name.trim().split(/\s+/)[0] + '. ' : '';
  if (trackingIssue) {
    committed.p_state = { ...context.state, tracking_issue:trackingIssue };
    delete committed.p_state.returning_lookup;
    return committed;
  }
  if (context.state.tracking_issue && decision.intent === 'esclarecer_codigo') {
    committed.p_state = context.state;
    return committed;
  }
  if (context.state.tracking_issue) delete committed.p_state.tracking_issue;
  if (lookup === 'summary' || lookup === 'ambiguous_code') {
    committed.p_state = { ...context.state };
    delete committed.p_state.tracking_issue;
    if (lookup === 'summary') {
      committed.p_state.returning_lookup = {code:context.returning.code,summary_only:true,summary:context.returning.summary};
    }
    return committed;
  }
  if (lookup === 'confirm_contact') {
    committed.p_state = { ...context.state };
    delete committed.p_state.returning_lookup;
    if (lookup === 'confirm_contact') committed.p_state.returning_lookup = {code:context.returning.code};
    return committed;
  }
  if (context.state.returning_lookup?.code && (decision.intent === 'confirmar_vinculo' ||
      context.state.returning_lookup.summary_only === true && !decision.new_quote_context)) {
    committed.p_state = context.state;
    return committed;
  }
  if (lookup === 'ambiguous' && !decision.new_quote_context) {
    const cases = context.returning.cases || [];
    committed.p_state = { ...context.state, returning_choices: cases.map(item=>item.id) };
    const labels = cases.map((item,i)=> (i+1) + '. ' + [item.product || 'Solicitação sem produto informado',item.company].filter(Boolean).join(' · '));
    committed.p_answer = { text:greeting + 'Encontrei mais de uma solicitação. Qual você quer retomar? Responda com o número da opção ou com o Código Lino.\n\n' + labels.join('\n'),source:'sdr' };
    return committed;
  }
  if (returning && (onlyCode || onlyPhone || context.returning?.lookup === 'selected') && !decision.new_quote_context) {
    committed.p_state = context.state;
    committed.p_answer = { text:greeting + (returning.product ? 'Encontrei sua solicitação de ' + returning.product + '. ' : 'Encontrei seu atendimento. ') +
      'Como posso ajudar com essa solicitação?',source:'sdr' };
    return committed;
  }
  if (decision.new_quote_context) {
    context.state = decision.new_quote_context;
    context.handoff = null;
    decision = { ...decision, quote_intent:true, human_requested:false, summary_accepted:false };
  }
  const handoff = context.handoff;
  const commercialSeller = handoff?.assigned === true || handoff?.destination &&
    !['suporte_humano','comex','compras','rh'].includes(handoff.destination);
  const assigned = Boolean(commercialSeller && handoff?.delivered_at);
  if (!assigned && (handoff?.opportunity_id || context.state.commercial?.existing_seller) && !decision.new_quote_context) {
    const intent = decision.support_intent;
    committed.p_state = { ...committed.p_state, commercial:context.state.commercial };
    const hasComplement = Object.entries(decision.patch || {}).some(([key, entry]) =>
      JSON.stringify(entry?.value) !== JSON.stringify(context.state.facts?.[key]?.value)) ||
      committed.p_attachments?.some(item => item.status !== 'ilegivel' && item.text);
    if (handoff?.opportunity_id && (intent === 'complemento_cotacao' && hasComplement ||
      ['acompanhamento_pedido','cobranca_atendimento'].includes(intent))) {
      committed.p_answer.case_action = {type:intent, opportunity_id:handoff.opportunity_id, pending:'entrega_inicial'};
      if (intent === 'complemento_cotacao') committed.p_answer.case_action.patch = decision.patch;
      if (intent === 'cobranca_atendimento') {
        committed.p_state.sla = {...context.state.sla, faltas:0, last_pending_claim_at:new Date().toISOString()};
      }
    }
    if (!committed.p_answer.text.trim()) throw new Error('Resposta contextual ausente');
    return committed;
  }
  if (assigned) {
    const handled = handleSupportMode(committed, context, decision);
    if (handled) return handled;
  }
  const activePrior = context.state.commercial ?? {};
  const state = committed.p_state;
  const message = (context.payload.message || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().trim();
  const impatientSellerRequest = /\b(?:cad[eê]|quem vai me atender|tem alguem querendo vender|so quero minha cotacao|passa (?:pro|para o) vendedor)\b/.test(message);
  const explicitHumanPattern = /\b(?:(?:quero|preciso|gostaria de)\s+(?:falar|conversar)|(?:me\s+)?(?:encaminh[ae]r?|transfir[ae]|transferir|pass[ae]r?))\b.{0,35}\b(?:human[oa]|atendente|vendedor[ae]?|pessoa)\b|\b(?:atendimento\s+humano|falar\s+com\s+(?:um[a]?\s+)?(?:human[oa]|atendente|vendedor[ae]?|pessoa))\b/;
  const explicitHuman = (decision.human_requested === true || impatientSellerRequest)
    && (explicitHumanPattern.test(message) || impatientSellerRequest)
    && !/\b(?:nao quero|nao preciso|sem falar|nao me)\b/.test(message);
  const affirmative = acceptsCommercialSummary(message, activePrior, context.revision);
  const quoteDeclined = /\b(?:sem (?:pedido de |pedir )?|nao (?:quero|preciso de|vou pedir) (?:uma? )?)(?:orcamento|cotacao)\b/.test(message);
  const quoteIntent = !quoteDeclined && (activePrior.quoteRequested === true || decision.quote_intent === true || quoteIntentFromMessage(message));
  if (decision.sector === 'suporte_humano' && !explicitHuman
      && (state.facts?.segmento?.value || Number(activePrior.activityQuestions ?? 0) < 2)) {
    decision = {...decision,sector:''};
  }
  const hasSector = ['comex', 'compras', 'rh', 'suporte_humano'].includes(decision.sector);
  if (!explicitHuman && !quoteIntent && !hasSector) return committed;
  if (!explicitHuman && !hasSector && state.technical?.awaiting_technical_answer === true) {
    committed.p_state = { ...state, commercial: { ...activePrior, quoteRequested: quoteIntent } };
    if (committed.p_answer.source !== 'catalogo_sdr') {
      committed.p_answer.text = 'Registrei seu pedido de cotação. Para avançar, precisamos esclarecer o ponto técnico indicado na resposta anterior.';
    }
    return committed;
  }

  if (affirmative && activePrior.summary && activePrior.summaryRevision === context.revision) {
    committed.p_state = { ...state, facts: context.state.facts };
  }
  const result = commercialTurnConfirmed(committed, context, decision, explicitHuman, quoteIntent, affirmative);
  if (result.p_destination && returning?.source === 'legacy' && !decision.new_quote_context) {
    result.p_state.commercial = activePrior;
    result.p_answer = {text:'Registrei os dados na solicitação que você retomou. O encaminhamento está pendente.',source:'sdr',
      case_action:{type:'retomada_sdr',opportunity_id:returning.id,pending:'roteamento',destination:result.p_destination,patch:result.p_state.facts}};
    delete result.p_destination;
    delete result.p_request_key;
  }
  return result;
}

function commercialTurnConfirmed(committed, context, decision, explicitHuman, quoteIntent, affirmative) {
  const state = committed.p_state;
  const facts = state.facts ?? {};
  const fact = key => facts[key]?.value;
  const prior = context.state.commercial ?? {};
  const product = fact('produto') ?? ({
    tela_antiofuscante: 'Tela antiofuscante', chapa_perfurada: 'Chapa perfurada',
    chapa_expandida: 'Chapa expandida', chapa_recalcada: 'Chapa recalcada',
    gradil_metalico: 'Gradil metálico', portao_gradil: 'Portão de gradil',
    grade_piso: 'Grade de piso', degrau_grade_piso: 'Degrau de grade de piso',
    chapa_moeda: 'Chapa moeda', bobina_moeda: 'Bobina moeda', tela_moeda: 'Tela moeda',
    brise: 'Brise metálico', forro_metalico: 'Forro metálico',
  })[fact('produto_familia')];
  const visible = Object.entries(labels).flatMap(([key, label]) => {
    const value = key === 'produto' ? product : fact(key);
    if (value == null) return [];
    if (Array.isArray(value)) return value.length ? [label + ': ' + value.join('; ')] : [];
    if (typeof value === 'object') return [];
    return [label + ': ' + String(value)];
  });
  if (fact('segmento') === 'construcao') visible.push('Segmento: Construção');
  const totalArea = resolveCommercialArea(facts);
  if (totalArea && !/m²|m2|metros quadrados/i.test(String(fact('quantidade') || ''))) {
    visible.push('Área total: ' + totalArea.toLocaleString('pt-BR',{maximumFractionDigits:4}) + ' m²');
  }
  const psaConfirmed = isPsaArchitectureDemand(facts, decision, prior);
